Add `Current state`, `implementation details`, `acceptance criteria` for `design/feature_descriptions/B_254_released_cards_chat_logs.md`.&#x20;
update the field `status` in the markdown feature description file to `ready for implementation`.

Read all referenced files before you begin except `agents` files. it is possible that the file is not yet written. &#x20;
Ask any question if something is ambiguous or not yet clear.
Be brief, but never compress away the subject, timing, or causal chain. Define ambiguous technical phrases. use $caveman skill.

Do not stage or commit changes. You have no need for get at this time.

import { useId, useMemo, useState } from 'react'
import { displayActionsForContext, projectContextWithWorktree, type ActionContext } from '../../../../data/action_context'
import { dataService } from '../../../../services/data/data_service'
import { actionRunRegistry } from '../../../../services/actions/action_run_registry'
import { actionPromptDraftService } from '../../../../services/actions/action_prompt_draft_service'
import { cardAgentState } from '../../../../services/agents/card_agent_state'
import { isReleasedCardActionContext, RELEASED_CARD_RUN_MESSAGE } from '../../../../../../shared/released_card_actions.mjs'
import { useActions } from '../../../hooks/use_actions'
import { useProjectState } from '../../../hooks/use_project_state'
import { useProjectActionWorktree } from '../../../hooks/use_worktrees'
import { ActionPopupContent } from './action_popup_content'
import { resolveInitialActionId, type PersistedActionStates } from './action_popup_initial_action'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_content'

/**
 * Badge id plus the title shown in its tooltip. The title comes from the live snapshot so it
 * follows a card renamed while the popup stays open, and falls back to the title captured in the
 * context when the card is not in the snapshot.
 */
function resolvePopupTarget(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    if (context.kind === 'project') return { id: 'Project', title: null }
    if (context.kind !== 'card') return { id: null, title: null }

    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
    const card = cards.find(({ header }) => header.internalId === context.cardInternalId)

    return { id: card?.header.id ?? null, title: card?.header.title ?? context.title ?? null }
}

function resolveCardInternalId(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
    const card = context.cardInternalId
        ? cards.find(({ header }) => header.internalId === context.cardInternalId)
        : cards.find(({ path }) => path === context.file)

    return card?.header.internalId ?? context.cardInternalId ?? null
}

function resolveColumnDefaultActionId(context: ActionContext) {
    if (context.kind !== 'card' || !context.state) return undefined

    return dataService.getConfig()?.states.find(({ state }) => state === context.state)?.defaultActionId
}

function persistedActionStates(
    actions: ReturnType<typeof displayActionsForContext>,
    context: ActionContext,
    snapshot: ReturnType<typeof useProjectState>['snapshot'],
) {
    if (context.kind === 'project') {
        const conversations = dataService.agents.getProjectAgentConversationsSnapshot()

        return Object.fromEntries(actions.map(({ id }) => [
            id,
            cardAgentState(conversations.filter((conversation) => conversation.actionId === id)),
        ])) as PersistedActionStates
    }

    const cardInternalId = resolveCardInternalId(context, snapshot)
    if (!cardInternalId) return {}

    const conversations = dataService.agents.getAgentConversations(cardInternalId)

    return Object.fromEntries(actions.map(({ id }) => [
        id,
        cardAgentState(conversations.filter((conversation) => conversation.actionId === id)),
    ])) as PersistedActionStates
}

interface ActionPopupProps {
    anchorElement: HTMLElement | null
    context: ActionContext
    draggable?: boolean
    initialActionId?: string
    initialConversationPath?: string
    initialRunId?: string
    onActivate?: () => void
    onClose: () => void
    open?: boolean
    popupEntryId?: string
    popupVisible?: boolean
    stackPosition?: number
}

/** Universal action selector and run popup for the supplied context. */
export function ActionPopup(props: ActionPopupProps) {
    const { anchorElement, context, initialActionId, initialConversationPath, initialRunId, onClose, open } = props
    const { actions: loadedActions } = useActions()
    const { project, snapshot } = useProjectState()
    const projectActionWorktree = useProjectActionWorktree()
    const effectiveContext = useMemo(
        () => projectContextWithWorktree(context, projectActionWorktree),
        [context, projectActionWorktree],
    )
    const actions = useMemo(() => displayActionsForContext(loadedActions, effectiveContext), [effectiveContext, loadedActions])
    const [selectedActionId, setSelectedActionId] = useState<string | null>(() => resolveInitialActionId(
        actions,
        initialActionId,
        actionRunRegistry.getContextActiveSnapshot(effectiveContext),
        persistedActionStates(actions, effectiveContext, snapshot),
        resolveColumnDefaultActionId(effectiveContext),
    ))
    const [fullHeight, setFullHeight] = useState(false)
    const titleId = useId()
    // A run that edits its own card changes the context (state, title, worktree), so the
    // selected action can drop out of the filtered list mid-run. Keep it selectable instead
    // of closing the popup or silently switching to another action.
    const retainedAction = selectedActionId ? loadedActions.find(({ id }) => id === selectedActionId) ?? null : null
    const selectedAction = actions.find(({ id }) => id === selectedActionId) ?? retainedAction ?? actions[0] ?? null
    const selectableActions = selectedAction && !actions.some(({ id }) => id === selectedAction.id)
        ? [...actions, selectedAction]
        : actions
    const { id: target, title: targetTitle } = resolvePopupTarget(context, snapshot)
    const releasesFolder = dataService.getConfig()?.releasesFolder
    const readOnlyMessage = releasesFolder && isReleasedCardActionContext(effectiveContext, releasesFolder)
        ? RELEASED_CARD_RUN_MESSAGE
        : null

    const handleSelectAction = (actionId: string) => {
        setSelectedActionId(actionId)
    }

    const handleClose = () => {
        actionPromptDraftService.deleteEmptyDrafts()
        onClose()
    }

    const handleToggleFullHeight = () => setFullHeight((current) => !current)

    if (!selectedAction) return null

    return (
        <ActionPopupContent
            {...props}
            action={selectedAction}
            actions={selectableActions}
            assignmentContext={effectiveContext}
            baseContext={context}
            fullHeight={fullHeight}
            initialConversationPath={selectedAction.id === initialActionId ? initialConversationPath : undefined}
            initialRunId={selectedAction.id === initialActionId ? initialRunId : undefined}
            onClose={handleClose}
            onSelectAction={handleSelectAction}
            onToggleFullHeight={handleToggleFullHeight}
            open={open ?? !!anchorElement}
            primaryPath={project?.rootPath ?? project?.id ?? null}
            readOnlyMessage={readOnlyMessage}
            target={target}
            targetTitle={targetTitle}
            titleId={titleId}
        />
    )
}

import { Box, Button, Tooltip } from '@mui/material'
import Circle from 'mdi-material-ui/Circle'
import HelpCircleOutline from 'mdi-material-ui/HelpCircleOutline'
import Play from 'mdi-material-ui/Play'
import type { MouseEvent } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { CardHeader } from '../../../../data/data_types'
import { cardPopupService } from '../../../../services/card_popup_service'
import { agentStateDescription } from '../../../../services/agents/card_agent_state'
import { useCardAgentState } from '../../../hooks/use_agent_acknowledgements'
import { useRunningActionForContext } from '../../../hooks/use_action_runs'
import { useProjectReadOnly } from '../../../hooks/use_project_read_only'

interface CardRunButtonProps {
    card: { header: Pick<CardHeader, 'internalId'> }
    context: ActionContext
}

/** Opens the card action selector and run popup, and surfaces the card's agent state. */
export function CardRunButton({ card, context }: CardRunButtonProps) {
    const agentState = useCardAgentState(card.header.internalId)
    const runningRun = useRunningActionForContext(context)
    const readOnly = useProjectReadOnly()
    const liveStatus = runningRun?.status
    const isQueued = liveStatus === 'queued'
    const isWaiting = liveStatus ? liveStatus === 'waitingForInput' : agentState === 'waiting for input'
    const isRunning = liveStatus ? liveStatus === 'running' : agentState === 'running'
    const isUnseen = !isQueued && !isWaiting && !isRunning && agentState === 'unseen result'
    const stateDescription = isQueued
        ? 'Action is queued'
        : isWaiting
            ? agentStateDescription('waiting for input')
            : isRunning && agentState !== 'running'
                ? 'Action is running'
                : agentStateDescription(agentState)
    const accent = isWaiting ? 'warning.main' : isUnseen ? 'info.main' : 'primary.main'
    const handleRun = (event: MouseEvent<HTMLButtonElement>) => {
        cardPopupService.toggleAction(context, event.currentTarget)
    }

    const button = (
        <Box
            sx={(theme) => ({
                borderRadius: 99,
                display: 'inline-flex',
                overflow: 'hidden',
                p: isRunning ? '1.5px' : 0,
                position: 'relative',
                ...(isRunning && {
                    '@keyframes md2-run-spin': { to: { transform: 'rotate(1turn)' } },
                    '&::before': {
                        animation: 'md2-run-spin 1s linear infinite',
                        background: `conic-gradient(from 0deg, ${theme.palette.primary.main}, transparent 55%)`,
                        content: '""',
                        inset: '-50%',
                        pointerEvents: 'none',
                        position: 'absolute',
                    },
                }),
            })}
        >
            <Button
                aria-label={stateDescription ? `Run â€” ${stateDescription}` : 'Run'}
                disabled={readOnly}
                onClick={handleRun}
                size="small"
                startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                sx={{
                    bgcolor: 'background.paper',
                    borderColor: isRunning ? 'transparent' : isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    borderRadius: 99,
                    color: isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    fontSize: 11.5,
                    height: 26,
                    minWidth: 0,
                    position: 'relative',
                    px: 1.25,
                    zIndex: 1,
                    '&:hover': { bgcolor: 'background.paper' },
                }}
                variant="outlined"
            >
                Run
            </Button>
            {isWaiting ? <HelpCircleOutline sx={{ color: accent, fontSize: 11, position: 'absolute', right: -2, top: -2, zIndex: 2 }} /> : null}
            {isUnseen ? <Circle sx={{ color: accent, fontSize: 8, position: 'absolute', right: 0, top: 0, zIndex: 2 }} /> : null}
        </Box>
    )

    return (
        <Tooltip title={stateDescription ?? ''}>{button}</Tooltip>
    )
}

import { Box } from '@mui/material'
import { memo, useCallback, useEffect, useState } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { ListCardCommitDiffPanel } from '../card_view/list_card_commit_diff_panel'
import { cardMarkdownDataSource, type CardDocumentClosedDetail } from '../editor/data_sources/card_markdown_data_source'
import { MarkdownDocumentHistoryStore } from '../editor/history/markdown_document_history_store'
import { MarkdownEditor } from '../editor/markdown_editor'
import type { MarkdownToolbarContext } from '../editor/toolbar/markdown_toolbar_context'
import { ListEditorToolbarControls } from './list_editor_toolbar_controls'
import { useProjectReadOnly } from '../hooks/use_project_read_only'
import { attachFilesToCardMarkdown } from '../../services/attachments/attachment_workflow'
import { resolveCardImageSource } from '../../services/attachments/card_image_source'

interface CardEditorProps {
    cardTypes: CardTypeConfig[]
    statusColors: Map<string, string>
}

/** Lifetime-stable list-card editor with private history. */
export const CardEditor = memo(function CardEditor(props: CardEditorProps) {
    const { cardTypes, statusColors } = props
    const readOnly = useProjectReadOnly()
    const [historyStore] = useState(() => new MarkdownDocumentHistoryStore())
    const handleImagePaste = useCallback(
        (file: File, insertMarkdown: (markdown: string) => void) => cardMarkdownDataSource.pasteImage('list-card', file, insertMarkdown),
        [],
    )
    const handleAttachments = useCallback((files: File[], insertMarkdown: (markdown: string) => void) => {
        const card = cardMarkdownDataSource.getActiveCard('list-card')
        if (!card) throw new Error('Cannot attach files without an active list card')

        return attachFilesToCardMarkdown(card.path, files, insertMarkdown)
    }, [])
    const handleImagePreview = useCallback(async (src: string) => {
        const card = cardMarkdownDataSource.getActiveCard('list-card')
        if (!card) return src

        return resolveCardImageSource(card.path, src)
    }, [])

    useEffect(() => {
        const handleCardDocumentClosed = (event: Event) => {
            const { binding, document } = (event as CustomEvent<CardDocumentClosedDetail>).detail
            if (binding !== 'list-card') return

            historyStore.discardDocument(document)
        }
        cardMarkdownDataSource.addEventListener('cardDocumentClosed', handleCardDocumentClosed)

        return () => {
            cardMarkdownDataSource.removeEventListener('cardDocumentClosed', handleCardDocumentClosed)
        }
    }, [historyStore])

    const toolbarContents = useCallback((toolbarContext: MarkdownToolbarContext) => (
        <ListEditorToolbarControls
            cardTypes={cardTypes}
            historyStore={historyStore}
            onAttachFiles={toolbarContext.onAttachFiles}
            readOnly={readOnly}
            statusColors={statusColors}
        />
    ), [cardTypes, historyStore, readOnly, statusColors])

    return (
        <Box sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}>
            <ListCardCommitDiffPanel>
                <MarkdownEditor
                    attachmentHandler={handleAttachments}
                    binding="list-card"
                    dataSource={cardMarkdownDataSource}
                    historyStore={historyStore}
                    imagePasteHandler={handleImagePaste}
                    imagePreviewHandler={handleImagePreview}
                    readOnly={readOnly}
                    toolbarContents={toolbarContents}
                />
            </ListCardCommitDiffPanel>
        </Box>
    )
})

import type { ActionRunStatus } from '../../../../data/action_run_types'
import type { ActionDefinition } from '../../../../data/action_types'
import type { ActiveActionRun } from '../../../../services/actions/action_run_registry'
import type { CardAgentState } from '../../../../services/agents/card_agent_state'

export type PersistedActionStates = Record<string, CardAgentState>

function liveActionStatuses(activeRuns: ActiveActionRun[]) {
    const statuses: Record<string, ActionRunStatus> = {}
    for (const { rootActionId, status } of activeRuns) {
        if (status === 'waitingForInput' || !statuses[rootActionId]) statuses[rootActionId] = status
    }

    return statuses
}

/** Resolves one popup action from explicit choice, active work, persisted attention state, column default, then selector order. */
export function resolveInitialActionId(
    actions: Pick<ActionDefinition, 'id'>[],
    initialActionId: string | undefined,
    activeRuns: ActiveActionRun[],
    persistedStates: PersistedActionStates,
    defaultActionId?: string,
) {
    if (initialActionId) return initialActionId

    const liveStatuses = liveActionStatuses(activeRuns)
    const runningAction = actions.find(({ id }) => {
        const liveStatus = liveStatuses[id]

        return liveStatus === 'queued'
            || liveStatus === 'running'
            || (!liveStatus && persistedStates[id] === 'running')
    })
    if (runningAction) return runningAction.id

    const attentionAction = actions.find(({ id }) => {
        const liveStatus = liveStatuses[id]
        const persistedState = persistedStates[id]

        return liveStatus === 'waitingForInput'
            || (!liveStatus && (persistedState === 'waiting for input' || persistedState === 'unseen result'))
    })

    const defaultAction = actions.find(({ id }) => id === defaultActionId)

    return attentionAction?.id ?? defaultAction?.id ?? actions[0]?.id ?? null
}

import { useEffect, useMemo } from 'react'
import { actionContextIdentity } from '../../../../data/action_context'
import {
    actionRunSettingsService,
} from '../../../../services/actions/action_run_settings_service'
import { AgentAction } from './agent_action'
import { ActionPopupFrame } from './action_popup_frame'
import { CommandAction } from './command_action'
import { createActionPopupBindings, worktreeValidationMessage } from './action_popup_runtime'
import type { ActionPopupContentProps, ActionPopupRuntime } from './action_popup_types'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_frame'

/** Selects the action-specific popup content while preserving its runtime for the selected action. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const { action, assignmentContext, initialConversationPath, initialRunId } = props
    const settingsContextIdentity = actionContextIdentity(assignmentContext)
    const settingsStore = useMemo(
        () => assignmentContext.cardInternalId
            ? actionRunSettingsService.getCardStore(assignmentContext.cardInternalId, action.id)
            : actionRunSettingsService.getSessionStore(action.id, settingsContextIdentity),
        [action.id, assignmentContext.cardInternalId, settingsContextIdentity],
    )
    const bindings = useMemo(
        () => createActionPopupBindings(action, assignmentContext, initialRunId, initialConversationPath),
        [action, assignmentContext, initialConversationPath, initialRunId],
    )
    useEffect(() => {
        bindings.usageValuesService.start()

        return () => {
            bindings.usageValuesService.stop()
            bindings.bindingStore.dispose()
            bindings.conversationStore.dispose()
        }
    }, [bindings])
    const runtime: ActionPopupRuntime = {
        ...bindings,
        runValidationError: worktreeValidationMessage(action, assignmentContext),
        settingsStore,
    }

    return (
        <ActionPopupFrame
            bindingStore={bindings.bindingStore}
            contentProps={props}
            conversationSearchService={bindings.conversationSearchService}
            conversationStore={bindings.conversationStore}
        >
            {action.type === 'agent'
                ? (
                    <AgentAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        popupEntryId={props.popupEntryId}
                        popupVisible={props.popupVisible}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                ) : (
                    <CommandAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                )}
        </ActionPopupFrame>
    )
}

