        const hadConversations = this.pinnedConversations.length > 0
        this.pinnedConversations = []
        this.pinnedConversationCandidates.clear()
        this.pinnedLoad = null
        this.pinnedLoadCompleted = false
        this.pinnedPopupOpen = false
