import type { CardActivityFile, ActionActivityRecord } from '../../../../../../shared/card_activity.mjs'
import { BUILTIN_CUSTOM_PROMPT, CUSTOM_PROMPT_ACTION_ID, type ActionDefinition } from '../../../../data/action_types'
